		protected virtual USCCountryLookups GetNewLookups()
		{
			return new USCCountryLookups(this);
		}

		USCCountryLookups fLookups;

		#endregion

		#region Validation

		protected override void RunPreSaveValidationCore()
		{
			Validation.ValidateAll();
			base.RunPreSaveValidationCore(); // call RunPreSaveValidationCore() on all children then fire OnNotificationsChanged()
		}

		public USCCountryValidation Validation
		{
			get { return GetNewValidation(); }
		}

		protected virtual USCCountryValidation GetNewValidation()
		{
			return new USCCountryValidation(this);
		}

		#endregion
	}
